using System;using System.Collections.Generic;using UnityEngine;using Simus.City;
namespace Simus.StateDensity {
public sealed class CityStateDensity:MonoBehaviour {
 [Serializable]public class Binding{public string id,stat;public GameObject[] targets;public GameObject physicalSource;public bool high;public float threshold;public bool inclusive;}
 public Binding[] bindings=Array.Empty<Binding>();public CityStatePoller source;public bool previewEnabled;public float happiness=50,safety=50,cleanliness=50,pollution=50;public bool hasLiveData;public string status="No city state: hidden";
 readonly Dictionary<GameObject,ParticleSystem[]> particles=new Dictionary<GameObject,ParticleSystem[]>();
 void OnEnable(){particles.Clear();foreach(var b in bindings)foreach(var go in b.targets)if(go)particles[go]=go.GetComponentsInChildren<ParticleSystem>(true);foreach(var ps in GetComponentsInChildren<ParticleSystem>(true)){var main=ps.main;main.cullingMode=ParticleSystemCullingMode.AlwaysSimulate;}ResetHidden();}void Update(){if(!previewEnabled){if(!source)source=FindFirstObjectByType<CityStatePoller>();var s=source?source.Store.Current:null;hasLiveData=s!=null;if(s!=null){happiness=(float)s.Happiness;safety=(float)s.Safety;cleanliness=(float)s.Cleanliness;if(s.OverallPollution.HasValue)pollution=(float)s.OverallPollution.Value;status="CityState aggregate values";}else status="No city state: hidden";}Apply();}
 public void SetPreview(float h,float s,float c,float p){previewEnabled=true;happiness=h;safety=s;cleanliness=c;pollution=p;Apply();}
 public void Apply(){foreach(var b in bindings){float v=b.stat=="HAP"?happiness:b.stat=="SAF"?safety:b.stat=="CLN"?cleanliness:pollution;bool available=previewEnabled||hasLiveData;if(!previewEnabled&&b.stat=="POL")available=available&&source&&source.Store.Current!=null&&source.Store.Current.OverallPollution.HasValue;bool on=available&&(b.high?v>b.threshold:(b.inclusive?v<=b.threshold:v<b.threshold));if(b.physicalSource&&!b.physicalSource.activeInHierarchy)on=false;foreach(var go in b.targets)if(go){if(go.activeSelf!=on)go.SetActive(on);foreach(var ps in particles.TryGetValue(go,out var systems)?systems:Array.Empty<ParticleSystem>()){if(on&&!ps.isPlaying)ps.Play(true);else if(!on)ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}}}}
 public void ResetHidden(){previewEnabled=false;hasLiveData=false;foreach(var b in bindings)foreach(var go in b.targets)if(go)go.SetActive(false);}
 #if UNITY_EDITOR || DEVELOPMENT_BUILD
 bool show;void OnGUI(){if(GUI.Button(new Rect(12,12,210,28),"City stat visual preview"))show=!show;if(!show)return;GUILayout.BeginArea(new Rect(12,48,300,320),GUI.skin.box);GUILayout.Label(status);previewEnabled=GUILayout.Toggle(previewEnabled,"Preview (no server changes)");happiness=Slider("Happiness",happiness);safety=Slider("Safety",safety);cleanliness=Slider("Cleanliness",cleanliness);pollution=Slider("Pollution",pollution);if(GUILayout.Button("Poor cleanliness / polluted"))SetPreview(50,50,15,90);if(GUILayout.Button("Clean / low pollution"))SetPreview(70,70,90,10);if(GUILayout.Button("Return to live data"))ResetHidden();GUILayout.EndArea();}float Slider(string n,float v){GUILayout.Label(n+" "+Mathf.RoundToInt(v));return GUILayout.HorizontalSlider(v,0,100);}
 #endif
}}
